export type RetryDecision =
  | { retry: false; reason: "status" | "budget" }
  | { retry: true; delayMs: number };

export class RetryController {
  plan(status: number, attempt: number, retryAfterMs?: number): RetryDecision {
    if (!Number.isInteger(attempt) || attempt < 0) {
      throw new RangeError("attempt must be a non-negative integer");
    }
    if (status !== 429 && status !== 503) {
      return { retry: false, reason: "status" };
    }
    if (attempt >= 3) {
      return { retry: false, reason: "budget" };
    }
    const exponential = Math.min(100 * 2 ** attempt, 500);
    const requested = retryAfterMs !== undefined && Number.isFinite(retryAfterMs) && retryAfterMs >= 0
      ? retryAfterMs
      : exponential;
    return { retry: true, delayMs: Math.min(Math.max(exponential, requested), 500) };
  }
}

